import { useQuery } from "@tanstack/react-query";
import dayjs from "dayjs";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Badge } from "@/components/ui/badge";
import { Skeleton } from "@/components/ui/skeleton";

import { PatientAppShell } from "@/components/Patient/PatientAppShell";

import { usePatientContext } from "@/hooks/usePatientUser";

import query from "@/Utils/request/query";
import { formatName } from "@/Utils/utils";
import patientPortalApi from "@/types/emr/patientPortal/patientPortalApi";

import {
  isObservationFlagged,
  observationLabel,
  observationValueLabel,
  referenceRangeLabel,
  reportFlagSummary,
  reportTitle,
} from "./records/reportUtils";

function MetaField({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex flex-col">
      <span className="text-[11px] text-gray-500">{label}</span>
      <span className="text-[12.5px] font-semibold text-gray-900">{value}</span>
    </div>
  );
}

export default function DiagnosticReportDetail({ id }: { id: string }) {
  const { t } = useTranslation();
  const { tokenData } = usePatientContext();

  const { data: report, isLoading } = useQuery({
    queryKey: ["portal-diagnostic-report", id],
    queryFn: query(patientPortalApi.getDiagnosticReport, {
      pathParams: { id },
      headers: { Authorization: `Bearer ${tokenData?.token}` },
    }),
    enabled: !!tokenData?.token,
  });

  const observations = report?.observations ?? [];
  const flags = report ? reportFlagSummary(report) : 0;

  return (
    <PatientAppShell
      title={report ? reportTitle(report, t) : t("diagnostic_report")}
      backTo="/patient/records?tab=reports"
      hideTabs
    >
      <div className="flex flex-col gap-3 p-4">
        {isLoading || !report ? (
          <>
            <Skeleton className="h-16 w-full rounded-2xl" />
            <Skeleton className="h-64 w-full rounded-2xl" />
          </>
        ) : (
          <>
            <div className="flex flex-wrap gap-4 rounded-2xl border border-gray-200 bg-white p-4">
              <MetaField
                label={t("reported")}
                value={dayjs(report.created_date).format("DD MMM, h:mm A")}
              />
              {report.encounter?.facility?.name && (
                <MetaField
                  label={t("facility")}
                  value={report.encounter.facility.name}
                />
              )}
              {report.encounter?.patient?.name && (
                <MetaField
                  label={t("patient")}
                  value={report.encounter.patient.name}
                />
              )}
            </div>

            {flags > 0 && (
              <Badge variant="yellow" className="self-start">
                {t("patient_records__flagged_count", { count: flags })}
              </Badge>
            )}

            {observations.length > 0 && (
              <div className="overflow-hidden rounded-2xl border border-gray-200 bg-white">
                <div className="grid grid-cols-[1.5fr_0.9fr_1fr] gap-2 border-b border-gray-200 bg-gray-50 px-3.5 py-2.5">
                  <span className="text-[10.5px] font-bold uppercase tracking-wide text-gray-500">
                    {t("test")}
                  </span>
                  <span className="text-[10.5px] font-bold uppercase tracking-wide text-gray-500">
                    {t("result")}
                  </span>
                  <span className="text-right text-[10.5px] font-bold uppercase tracking-wide text-gray-500">
                    {t("patient_records__reference")}
                  </span>
                </div>
                {observations.map((observation) => {
                  const flagged = isObservationFlagged(observation);
                  const reference = referenceRangeLabel(observation);
                  return (
                    <div
                      key={observation.id}
                      className="grid grid-cols-[1.5fr_0.9fr_1fr] items-center gap-2 border-b border-gray-100 px-3.5 py-3 last:border-b-0"
                    >
                      <span className="text-[13.5px] text-gray-900">
                        {observationLabel(observation, t)}
                      </span>
                      <span
                        className={cn(
                          "font-mono text-sm font-bold",
                          flagged ? "text-warning-700" : "text-gray-900",
                        )}
                      >
                        {observationValueLabel(observation)}
                        {observation.value?.unit?.display && (
                          <span className="ml-1 font-sans text-[11px] font-normal text-gray-500">
                            {observation.value.unit.display}
                          </span>
                        )}
                      </span>
                      <span className="text-right text-[11.5px] text-gray-600">
                        {reference ??
                          observation.interpretation?.display ??
                          "-"}
                      </span>
                    </div>
                  );
                })}
              </div>
            )}

            {report.conclusion && (
              <div className="flex flex-col gap-1.5 rounded-2xl border border-gray-200 bg-gray-50 p-4">
                <span className="text-[13px] font-bold text-gray-900">
                  {t("conclusion")}
                </span>
                <span className="text-[12.5px] leading-relaxed text-gray-600">
                  {report.conclusion}
                </span>
              </div>
            )}

            {report.note && (
              <p className="text-[12.5px] leading-relaxed text-gray-600">
                {report.note}
              </p>
            )}

            <div className="rounded-2xl border border-gray-200 bg-gray-50 px-3.5 py-3">
              <span className="text-xs text-gray-600">
                {t("patient_records__verified_by")}{" "}
                <span className="font-semibold text-gray-900">
                  {formatName(report.updated_by ?? report.created_by)}
                </span>
              </span>
            </div>
          </>
        )}
      </div>
    </PatientAppShell>
  );
}

import dayjs from "dayjs";
import { CalendarDays, ChevronRight } from "lucide-react";
import { Link } from "raviger";
import { useState } from "react";
import { useTranslation } from "react-i18next";

import { cn } from "@/lib/utils";

import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { EmptyState } from "@/components/ui/empty-state";
import { Skeleton } from "@/components/ui/skeleton";

import { PatientAppShell } from "@/components/Patient/PatientAppShell";

import { usePatientAppointments } from "@/hooks/usePatientPortalData";

import { renderTokenNumber } from "@/types/tokens/token/token";
import {
  APPOINTMENT_STATUS_COLORS,
  PublicAppointment,
  SchedulableResourceType,
  formatScheduleResourceName,
} from "@/types/scheduling/schedule";

type VisitsTab = "upcoming" | "history";

function UpcomingVisitCard({
  appointment,
}: {
  appointment: PublicAppointment;
}) {
  const { t } = useTranslation();
  const start = dayjs(appointment.token_slot.start_datetime);
  const canReschedule =
    appointment.resource_type === SchedulableResourceType.Practitioner;

  return (
    <div className="flex flex-col gap-3 rounded-2xl border border-primary-200 bg-primary-50 p-4">
      <div className="flex items-center justify-between">
        <span className="text-[10.5px] font-bold uppercase tracking-widest text-primary-700">
          {start.fromNow()}
        </span>
        {appointment.token && (
          <Badge variant="primary">
            {t("token")} {renderTokenNumber(appointment.token)}
          </Badge>
        )}
      </div>
      <div className="flex items-start gap-3">
        <div className="w-[52px] shrink-0 rounded-xl border border-primary-200 bg-white py-1.5 text-center">
          <div className="text-[10px] font-bold uppercase tracking-wide text-primary-700">
            {start.format("ddd")}
          </div>
          <div className="text-xl font-bold leading-tight text-gray-900">
            {start.format("DD")}
          </div>
          <div className="text-[10px] text-gray-500">{start.format("MMM")}</div>
        </div>
        <div className="flex min-w-0 flex-col gap-0.5">
          <span className="font-bold text-gray-900">
            {formatScheduleResourceName(appointment)}
          </span>
          <span className="text-[13px] text-gray-600">
            {start.format("h:mm A")} · {appointment.facility.name}
          </span>
        </div>
      </div>
      <div className="grid grid-cols-2 gap-2">
        <Button variant="outline" size="sm" asChild>
          <Link href={`/patient/visits/${appointment.id}`}>
            {t("view_details")}
          </Link>
        </Button>
        {canReschedule && (
          <Button size="sm" asChild>
            <Link
              href={`/facility/${appointment.facility.id}/appointments/${appointment.resource.id}/reschedule/${appointment.id}`}
            >
              {t("reschedule")}
            </Link>
          </Button>
        )}
      </div>
    </div>
  );
}

function PastVisitRow({ appointment }: { appointment: PublicAppointment }) {
  const { t } = useTranslation();
  const start = dayjs(appointment.token_slot.start_datetime);
  const isMissed =
    appointment.status === "noshow" || appointment.status === "cancelled";

  return (
    <Link
      href={`/patient/visits/${appointment.id}`}
      className={cn(
        "flex items-center gap-3 rounded-2xl border border-gray-200 bg-white p-3.5 hover:border-gray-300",
        isMissed && "opacity-75",
      )}
    >
      <div className="w-11 shrink-0 text-center">
        <div className="text-[9.5px] font-bold uppercase tracking-wide text-gray-500">
          {start.format("MMM")}
        </div>
        <div className="text-lg font-bold leading-tight text-gray-900">
          {start.format("DD")}
        </div>
      </div>
      <div className="flex min-w-0 flex-1 flex-col gap-0.5">
        <div className="flex items-center gap-2">
          <span className="truncate text-[14.5px] font-bold text-gray-900">
            {formatScheduleResourceName(appointment)}
          </span>
          <Badge variant={APPOINTMENT_STATUS_COLORS[appointment.status]}>
            {t(appointment.status)}
          </Badge>
        </div>
        <span className="truncate text-xs text-gray-600">
          {appointment.facility.name}
        </span>
      </div>
      <ChevronRight className="size-4 shrink-0 text-gray-400" />
    </Link>
  );
}

export default function PatientVisits() {
  const { t } = useTranslation();
  const [tab, setTab] = useState<VisitsTab>("upcoming");
  const { upcoming, history, isLoading } = usePatientAppointments();

  return (
    <PatientAppShell title={t("visits")}>
      <div className="flex gap-6 border-b border-gray-200 bg-white px-4">
        {(["upcoming", "history"] as const).map((key) => (
          <button
            key={key}
            type="button"
            onClick={() => setTab(key)}
            className={cn(
              "-mb-px border-b-[2.5px] pb-2.5 text-[14.5px] transition-colors",
              tab === key
                ? "border-primary-700 font-bold text-primary-700"
                : "border-transparent font-semibold text-gray-600",
            )}
          >
            {t(key)} · {key === "upcoming" ? upcoming.length : history.length}
          </button>
        ))}
      </div>

      <div className="flex flex-col gap-3 p-4">
        {isLoading ? (
          <Skeleton className="h-40 w-full rounded-2xl" />
        ) : tab === "upcoming" ? (
          upcoming.length ? (
            upcoming.map((appointment) => (
              <UpcomingVisitCard
                key={appointment.id}
                appointment={appointment}
              />
            ))
          ) : (
            <EmptyState
              icon={<CalendarDays className="size-6 text-primary-700" />}
              title={t("no_appointments")}
              description={t("patient_visits__no_upcoming_description")}
            />
          )
        ) : history.length ? (
          history.map((appointment) => (
            <PastVisitRow key={appointment.id} appointment={appointment} />
          ))
        ) : (
          <EmptyState
            icon={<CalendarDays className="size-6 text-primary-700" />}
            title={t("patient_visits__no_history")}
          />
        )}
      </div>
    </PatientAppShell>
  );
}

